package com.factory.management.service.ServiceImpl;import com.factory.management.dto.request.WarehouseRequest;import com.factory.management.dto.response.WarehouseResponse;import com.factory.management.entity.*;import com.factory.management.exception.*;import com.factory.management.repository.*;import com.factory.management.security.AuthorizationScope;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service@RequiredArgsConstructor public class WarehouseService{private final WarehouseRepository repository;private final FactoryRepository factories;private final AuthorizationScope scope;
@Transactional public WarehouseResponse create(WarehouseRequest r){String code=r.getCode().trim().toUpperCase();if(repository.existsByCodeIgnoreCase(code))throw new AppException(ErrorCode.WAREHOUSE_CODE_EXISTS);Warehouse v=new Warehouse();apply(v,r,code);v.setActive(r.getActive()==null||r.getActive());return response(repository.save(v));}@Transactional(readOnly=true)public List<WarehouseResponse>all(){return repository.findAllByActiveTrueOrderByCode().stream().filter(v->scope.canAccessFinancialScope(v.getFactory().getId(),null,null)).map(this::response).toList();}@Transactional public WarehouseResponse update(Long id,WarehouseRequest r){Warehouse v=find(id);if(!scope.canAccessFinancialScope(v.getFactory().getId(),null,null))throw new AppException(ErrorCode.ACCESS_DENIED);String code=r.getCode().trim().toUpperCase();if(repository.existsByCodeIgnoreCaseAndIdNot(code,id))throw new AppException(ErrorCode.WAREHOUSE_CODE_EXISTS);apply(v,r,code);if(r.getActive()!=null)v.setActive(r.getActive());return response(v);}@Transactional public void delete(Long id){Warehouse v=find(id);if(!scope.canAccessFinancialScope(v.getFactory().getId(),null,null))throw new AppException(ErrorCode.ACCESS_DENIED);v.setActive(false);}private void apply(Warehouse v,WarehouseRequest r,String code){if(!scope.canAccessFinancialScope(r.getFactoryId(),null,null))throw new AppException(ErrorCode.ACCESS_DENIED);Factory f=factories.findById(r.getFactoryId()).orElseThrow(()->new AppException(ErrorCode.FACTORY_ID_NOT_FOUND));v.setCode(code);v.setName(r.getName().trim());v.setFactory(f);v.setDescription(r.getDescription());}private Warehouse find(Long id){return repository.findById(id).orElseThrow(()->new AppException(ErrorCode.WAREHOUSE_NOT_FOUND));}private WarehouseResponse response(Warehouse v){return WarehouseResponse.builder().id(v.getId()).code(v.getCode()).name(v.getName()).factoryId(v.getFactory().getId()).factoryName(v.getFactory().getName()).description(v.getDescription()).active(v.getActive()).build();}}
